window.NDCampaignSpecs={"A1": [["通行安排", "任務附有內部通行安排。凜記住入口，還沒有追問誰能打開這些門。"], ["研究室出口", "出口只有一處。凜沿指定路線接近，封住赫爾曼的退路。"]], "A2": [["實驗台", "赫爾曼退向實驗台。凜必須先取得對抗優勢；實驗銃尚未開火。"]], "A3": [["內部通道", "清洗者使用只向內部開放的入口。凜藏在暗處，沒有踏進伏擊。"], ["清洗者的話", "「出外勤的還沒回來。等。」她記住裝備與行動方式，不接近首腦的遺體。"]], "S1": [["旅行記", "納爾瓦翻到沒去過的地方。他不能自由離開鐘樓。"], ["木製書籤", "朔把刻著生澀刀痕的書籤交給朋友。「那以後一起去。」"]], "S2": [["座標對照", "納爾瓦申請詠唱參數資料，取得了引域座標與實際聚落對照。"], ["居民紀錄", "被稱為已撤離的地區仍有人居住。"], ["死亡與採掘表", "儀式後有死亡紀錄，較早的犧牲區又出現在採掘名單；這尚不能直接證明暮晶來源。"]], "S3": [["出口", "朔安排朋友走向換班出口。他必須守住這段時間。"], ["柵門固定繩", "朋友通過後才能放下柵門，再從熟悉的維修階梯離開。"]], "T1": [["政府公告", "廣場仍公告無須撤離，有居民不願拋下家業。"], ["夜域前兆", "渡垣只能依前兆推估時間，必須先整理已勘查的備用路線。"]], "T2": [["落後的母女", "母親抱不動孩子。格蘭折返回去，先把女孩交給接應隊員。"], ["狹窄通道", "母親最後幾步跌倒。隊員已在另一端伸手接應。"]], "T3": [["盾內晶片", "格蘭插下救援盾。晶片只能擋住夜域幾秒，不會消滅夜域。"], ["母親的聲音", "方向感消失時，他循母親呼喚孩子的聲音說：「看著她。再一步就好。」"], ["接應的手", "隊員拉過母親，再抓住格蘭背帶。他放開即將崩裂的盾，讓隊員把自己拖走。"]], "E1": [["更換裝置", "換過裝置後，同一段錄音仍傳出女孩聲音，並非單純串音。"], ["礦物來源", "來源是數十年前毀滅的村莊。死亡名冊有相符記錄，但一句話不能確認身分。"]], "E2": [["導師留下的進入方式", "博士叫她明天別再來。伊芙得知事故後，循著他過去帶她走過的維修入口進入地下三層。"], ["研究副本", "取走副本：死亡、夜域停留時間與晶體純度存在關聯，形成暮晶需要漫長時間。"], ["設計與讀值", "取走備用設計及自動備份。開槍前已有未解異常，隨後回流紀錄中斷；不能還原在場人的所有行動。"]], "E3": [["備用裝置", "工作間的備用共振裝置可以改成可攜形式。"], ["保險片", "伊芙選用過載時碎裂、切斷能量路徑的保險片，並限制輸出。"]]};
window.NDCampaignShared=[["P1", "從路邊抱起的孩子", "p1-morwell-ruins", "納爾瓦被朔放走後，先把警告帶到受害聚落，再輾轉躲避追捕。一次經過夜域剛退的道路，他聽見嬰兒哭聲。", "他抱起孩子，隨身暮晶微微共振。官方已記載無生還者，身分登記會引來查驗。他留下孩子，取名「磷」。", [["道路旁", "周圍已沒有能照顧嬰兒的人。"], ["災區紀錄", "「無生還者」與眼前孩子矛盾，但納爾瓦不知道原因。"]]], ["P2", "納爾瓦隱瞞的事", "phosphor-memory", "磷在逃亡中長大。納爾瓦教她認路、辨認渡垣標誌，也教她走散後去哪裡等。行李裡一直留著同一枚書籤。", "納爾瓦害怕她被當成研究材料，於是不斷搬家。保護成了另一種隱瞞；磷開始自己讀紀錄、尋找答案。", [["陌生地名", "磷說出沒有去過的街道和店鋪。這是異常記憶，不是預知。"], ["舊地圖", "納爾瓦核對後沉默，沒有把自己的猜測告訴磷。"]]], ["P3", "資料終於接上", "phosphor-files", "納爾瓦透過中間管道得知赫爾曼的研究。博士死亡、尺烏覆滅後不久，一批行政抄件流到他手上。", "為了交接，他使用已停用的聯絡點。熟悉的路上多了盯梢者。他帶磷換藏身處，知道這次可能甩不掉。", [["晶化區規劃", "文件在移夜之前已列出人口、預期損耗與未來採掘權。"], ["封存案卷", "附有一張指向尺烏封存案卷的入庫索引；索引所指的命令正文不在這批資料裡。流出者的動機仍不明。"]]], ["P4", "分開以前", "phosphor-parting", "納爾瓦終於說出一直沒說的猜測，跟「無人生還」的紀錄有關；磷早就知道自己是路邊撿來的，這次她想知道的是剩下那半。", "他把磷送到約定出口，自己轉往線索指的方向。她等過接應時間，納爾瓦仍未出現，才按筆記去找渡垣。", [["書籤與文件", "納爾瓦交給磷木書籤、關鍵行政文件。"], ["災區暮晶", "納爾瓦把長年追查災區的暮晶交給她；它不是剛剛從死者生成。"], ["聯絡筆記", "渡垣是庇護地；守誓線索指向朔；曜火指向研究聯絡管道；尺烏是待查封存線索，不是求援對象。"]]], ["B1", "野狼與回報單", "tank-refusal", "磷依筆記在城外等朔，夜裡被野狼圍住。路過的渡垣隊員格蘭舉盾擊退狼群，把她帶回營地。", "副手問要不要把孩子的事回報協會。格蘭說不用，護送磷進城去見朔。「要把妳交給誰，我會先問妳。」", [["回報單", "副手已寫上地點與時間，姓名與來歷兩欄是空的。"], ["孩子的行李", "只有木書籤和一份手寫路線筆記，最後一頁寫著「去找朔」。"]]], ["B2", "書籤回來的那一天", "swordsman-return", "格蘭循筆記找到朔。多年過去，朔靠護送難民與商隊維生，仍留意失蹤納爾瓦的消息。", "「這是誰給妳的？」「我爸爸。」磷說分開時納爾瓦仍活著。朔收起行李，核對研究中轉處的路線，三人去找伊芙。", [["書籤背面的刀痕", "朔認出自己年輕時留下的刀痕。"], ["聯絡憑據", "納爾瓦不知道伊芙現址。憑據通向中轉處，伊芙逃離後曾在那裡留下新的聯繫方式。"]]], ["B3", "追著不屬於自己的記憶", "assassin-trail", "凜循事故碎片回到曜火外圍，只找到封鎖與焚毀的研究區。長年獨自行動的她，不會貿然相信方便的安排。", "她從外圍找到伊芙。磷、格蘭與朔也抵達了；磷攤開文件時露出尺烏封存標記。凜不知道內容，決定留下觀察。", [["物資交接消息", "有女研究員逃走，凜認出記憶裡的人，再循實際行跡追蹤。"], ["封存標記", "孩子、赫爾曼與尺烏可能受同一批人追趕，但標記不是完整答案。"]]], ["C1", "每一步都有來處", "party-arrival", "三人憑中轉處更新的聯繫方式找到伊芙。她最初只答應核對資料。每個人手上的線索都不完整。", "磷的文件補上移夜與人口紀錄；伊芙的副本補上暮晶研究。她們決定低強度觀察納爾瓦留下的災區暮晶。", [["磷的文件", "行政規劃有日期、人口與採掘安排。"], ["伊芙的副本", "研究支持死亡與暮晶的關係，尚未指出完整決策鏈。"]]], ["C2", "她還是個孩子", "gunner-stop", "普通測試只有雜訊。磷靠近時，浮出母親把嬰兒藏在路旁的畫面。「那個嬰兒……是我嗎？」", "伊芙關掉裝置並道歉：「不知道。這段還不能證明。」她說明風險與喊停的權利。磷沒有答應再測，只問：「先幫我找爸爸，好不好？」", [["讀值", "畫面清晰仍不等於身分確認。"], ["磷的顫抖", "格蘭按住伊芙的手。磷已經發抖，必須立即停止，不再提高共振。"]]], ["C3", "凜現身", "party-rescue", "追查人員沿失效聯絡管道抵達。朔守入口，格蘭護著磷退往後門。伊芙選擇資料，放棄大部分儀器。", "凜截斷後門追兵，帶眾人避開包圍。右手繃帶裂開，伊芙記住灼痕。安全後，磷主動拿出帶封存標記的入庫索引，向「尺烏的人」換取答案。", [["後門進路", "追兵抓住磷的行李。凜決定現身，不能讓孩子與線索被帶走。"]]], ["C4", "清洗不是臨時起意", "party-orders", "磷拿出納爾瓦留下的入庫索引。凜、伊芙與朔闖過文件庫外廊與內庫守衛，取回命令正本。", "「確認赫爾曼死亡後，執行尺烏整體封存；未歸建人員另行處置。」命令早於任務簽發。凜確認自己從一開始就被列為處置對象，但還不能指認最終簽發者。", [["入庫索引", "只寫文件庫、櫃位與件號，沒有命令正文。"], ["研究案號", "伊芙認出赫爾曼被收回權限的研究案。"], ["簽發日期", "簽發早於凜接到任務；簽署區被裁去，無法指認最終簽發者。"]]], ["C5", "伊芙的槍", "party-gun", "伊芙問右手傷口。凜糾正她對實驗銃位置的描述，承認自己在場。伊芙舉槍：「最後發生了什麼？」", "凜說出女孩殘響測試時一段未寫入報告的對話。伊芙仍可能被騙，但有了不能立刻抹去、必須查證的理由。", [["事故口述", "凜只描述射擊、擦傷、能量爆開與錯亂記憶，不假裝理解全部原理。"], ["回流讀值", "伊芙的資料支持異常回流，不能排除凜的其他行動。"], ["記憶片段", "「妳把聲音關掉了。他問妳，還要不要再聽一次。」這段私人對話是查證線索，不是無罪證明。"]]], ["C6", "留下來不是被原諒", "party-stay", "磷問：「剛剛妳說，只看到一段，不能知道全部。現在也是嗎？」格蘭提醒追兵可能回來，朔去查看路線。", "伊芙自主降低槍口：「我要查清楚。妳先留下。」凜接受條件。她只得到同行機會，沒有得到信任或原諒，其他人仍稱她「尺烏的人」。", [["同行條件", "不得私自拿走資料；接觸暮晶前必須告知。"], ["各自需要的答案", "伊芙要查導師死因，凜需要她辨認碎片的知識。"]]], ["C8", "第一號晶化觀測區", "party-zone", "伊芙整理災區資料，將舊地名、採掘編號與移夜日期放在一起，找出納爾瓦追查的幾條線交會的地方。", "資料稱它「第一號晶化觀測區」，納爾瓦的筆記也多次繞回這一帶。眼前更要緊的是找到納爾瓦，眾人決定循他追查的線去那個被封鎖的區域。", [["舊地名", "這裡是在比對資料，並非已抵達觀測區。"], ["追查方向", "拼合後的地圖只能指出納爾瓦追查的方向，不能保證他在那裡。"]]], ["C9", "沒有播完的錄音", "party-recorder", "磷筆記上的最後標記落在第一號晶化觀測區。五人進入被封閉的舊災區，找到一台壞掉的暮晶錄音裝置。", "修復後的錄音只播出一段調查紀錄，隨後被冥淵的咆哮打斷。五人擊退冥淵，納爾瓦與一名陌生女子從坑道另一頭跑來。", [["居住過的痕跡", "封閉區內有人生活過的痕跡，屋舍像是匆忙離開。"], ["納爾瓦的錄音裝置", "裝置已損壞；修復後只播出一段觀測區調查紀錄，隨後中斷。"], ["冥淵", "納爾瓦紀錄中的類人晶化個體，上身超過五成已晶體化；它們是什麼，仍不清楚。"]]]];

